
"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useParams } from "next/navigation";

type Producto = {
  documentId: string;
  name: string;
  slug?: string;
  description?: string;
  price: number;
  stock: number;
  image?: {
    url: string;
    name?: string;
  } | null;
};

export default function DetalleProducto() {
  const params = useParams();
  const documentId = params.documentId as string;

  const [producto, setProducto] = useState<Producto | null>(null);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    if (!documentId) return;

    async function cargarProducto() {
      try {
        setCargando(true);
        setError("");

        const respuesta = await fetch(
          `http://localhost:1337/api/products/${documentId}?populate=image`
        );

        if (!respuesta.ok) {
          throw new Error("No se pudo encontrar este producto.");
        }

        const resultado = await respuesta.json();
        setProducto(resultado.data);
      } catch {
        setError(
          "No fue posible cargar el producto. Comprueba que Strapi esté funcionando."
        );
      } finally {
        setCargando(false);
      }
    }

    cargarProducto();
  }, [documentId]);

  const formatoPrecio = (precio: number) =>
    new Intl.NumberFormat("es-CO", {
      style: "currency",
      currency: "COP",
      maximumFractionDigits: 0,
    }).format(precio);

    
function agregarAlCarrito() {
  if (!producto || producto.stock <= 0) {
    alert("Este producto no está disponible.");
    return;
  }

  try {
    const guardado = localStorage.getItem("elite-carrito");
    const carrito = guardado ? JSON.parse(guardado) : [];

    const existente = carrito.find(
      (item: { documentId: string }) =>
        item.documentId === producto.documentId
    );

    if (existente) {
      if (existente.cantidad >= producto.stock) {
        alert("Ya alcanzaste el stock disponible de este producto.");
        return;
      }

      existente.cantidad += 1;
    } else {
      carrito.push({
        documentId: producto.documentId,
        name: producto.name,
        price: Number(producto.price),
        stock: Number(producto.stock),
        cantidad: 1,
        image: producto.image ?? null,
      });
    }

    localStorage.setItem("elite-carrito", JSON.stringify(carrito));

    alert(`${producto.name} se agregó al carrito.`);
  } catch {
    alert("No se pudo guardar el producto.");
  }
}


  if (cargando) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-[#090909] px-6 text-white">
        <div className="text-center">
          <div className="mx-auto mb-5 h-12 w-12 animate-spin rounded-full border-4 border-[#d4af37]/20 border-t-[#d4af37]" />
          <p className="text-lg text-gray-300">
            Cargando producto...
          </p>
        </div>
      </main>
    );
  }

  if (error || !producto) {
    return (
      <main className="flex min-h-screen items-center justify-center bg-[#090909] px-6 text-white">
        <div className="max-w-md rounded-3xl border border-white/10 bg-[#141414] p-8 text-center">
          <p className="mb-4 text-5xl">⌕</p>
          <h1 className="mb-3 text-2xl font-bold">
            Producto no disponible
          </h1>
          <p className="mb-6 text-gray-400">
            {error || "No encontramos el producto que buscas."}
          </p>
          <Link
            href="/"
            className="inline-block rounded-xl bg-[#d4af37] px-6 py-3 font-bold text-black transition hover:bg-[#f0d675]"
          >
            Volver a la tienda
          </Link>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-[#090909] text-white">
      {/* Barra de navegación */}
      <header className="sticky top-0 z-20 border-b border-white/10 bg-[#090909]/95 backdrop-blur-md">
        <div className="mx-auto flex max-w-7xl items-center justify-between px-5 py-5 md:px-8">
          <Link href="/" className="text-2xl font-black tracking-wider">
            ÉLITE<span className="text-[#d4af37]"> STORE</span>
          </Link>

          <Link
            href="/"
            className="rounded-full border border-white/20 px-5 py-2 text-sm text-gray-200 transition hover:border-[#d4af37] hover:text-[#d4af37]"
          >
            ← Volver a la tienda
          </Link>
        </div>
      </header>

      {/* Detalle del producto */}
      <section className="mx-auto max-w-7xl px-5 py-10 md:px-8 md:py-16">
        <p className="mb-8 text-sm text-gray-500">
          <Link href="/" className="transition hover:text-[#d4af37]">
            Inicio
          </Link>
          <span className="mx-2">/</span>
          <span className="text-[#d4af37]">Producto</span>
        </p>

        <div className="grid items-center gap-10 lg:grid-cols-2 lg:gap-16">
          {/* Imagen */}
          <div className="group relative overflow-hidden rounded-3xl border border-white/10 bg-gradient-to-br from-[#1c1c1c] to-[#101010] p-5 md:p-10">
            <div className="absolute left-6 top-6 z-10 rounded-full border border-[#d4af37]/40 bg-black/60 px-4 py-2 text-xs font-bold uppercase tracking-widest text-[#d4af37]">
              Élite Store
            </div>

            {producto.image?.url ? (
              <img
                src={`http://localhost:1337${producto.image.url}`}
                alt={producto.image.name || producto.name}
                className="h-[320px] w-full object-contain transition duration-500 group-hover:scale-105 md:h-[460px]"
              />
            ) : (
              <div className="flex h-[320px] items-center justify-center text-center md:h-[460px]">
                <div>
                  <p className="mb-4 text-7xl">◇</p>
                  <p className="text-gray-500">
                    Imagen no disponible
                  </p>
                </div>
              </div>
            )}
          </div>

          {/* Información */}
          <div className="py-4">
            <p className="mb-4 text-sm font-bold uppercase tracking-[0.3em] text-[#d4af37]">
              Estilo que te representa
            </p>

            <h1 className="mb-5 text-4xl font-black leading-tight md:text-6xl">
              {producto.name}
            </h1>

            <div className="mb-6 h-1 w-20 rounded-full bg-[#d4af37]" />

            <p className="mb-8 text-base leading-8 text-gray-400 md:text-lg">
              {producto.description ||
                "Una excelente elección para complementar tu estilo. Descubre este producto de nuestra colección Élite Store."}
            </p>

            <div className="mb-8 rounded-2xl border border-white/10 bg-[#141414] p-6">
              <p className="mb-2 text-sm uppercase tracking-widest text-gray-500">
                Precio
              </p>

              <p className="text-4xl font-black text-[#d4af37] md:text-5xl">
                {formatoPrecio(Number(producto.price))}
              </p>

              <div className="mt-6 border-t border-white/10 pt-5">
                <div className="flex items-center justify-between gap-4">
                  <span className="text-gray-400">
                    Disponibilidad
                  </span>

                  <span
                    className={`rounded-full px-4 py-2 text-sm font-bold ${
                      producto.stock > 0
                        ? "bg-green-500/10 text-green-400"
                        : "bg-red-500/10 text-red-400"
                    }`}
                  >
                    {producto.stock > 0
                      ? "Disponible"
                      : "Agotado"}
                  </span>
                </div>

                <p className="mt-3 text-sm text-gray-500">
                  {producto.stock > 0
                    ? `${producto.stock} unidad(es) disponibles`
                    : "Por el momento no tenemos unidades disponibles."}
                </p>
              </div>
            </div>

            
{producto.stock > 0 ? (
  <button
    onClick={agregarAlCarrito}
    className="block w-full rounded-xl bg-[#d4af37] px-6 py-4 font-black text-black transition hover:-translate-y-1 hover:bg-[#f0d675]"
  >
    AGREGAR AL CARRITO
  </button>
) : (
  <button
    disabled
    className="block w-full cursor-not-allowed rounded-xl bg-gray-700 px-6 py-4 font-black text-gray-400"
  >
    PRODUCTO AGOTADO
  </button>
)}

<Link
  href="/carrito"
  className="mt-4 block w-full rounded-xl border border-white/20 px-6 py-4 text-center font-bold text-white transition hover:border-[#d4af37] hover:text-[#d4af37]"
>
  VER MI CARRITO
</Link>

            

            <p className="mt-5 text-center text-xs text-gray-600">
              ÉLITE STORE · Calidad, estilo y personalidad
            </p>
          </div>
        </div>
      </section>

      {/* Pie de página */}
      <footer className="border-t border-white/10 px-5 py-8 text-center">
        <p className="text-sm text-gray-500">
          © {new Date().getFullYear()} Élite Store. Todos los derechos reservados.
        </p>
      </footer>
    </main>
  );
}
